using System.Globalization;
using System.Text;
using Dapper;
using Sigov.Application.Common;
using Sigov.Application.Saneamento;
using Sigov.Infrastructure.Persistence.Dapper;

namespace Sigov.Infrastructure.Saneamento;

public sealed class SaneamentoRepository : ISaneamentoConsumidorRepository, ILigacaoSaneamentoRepository, IUnidadeConsumidoraRepository, IHidrometroRepository, ILeituraConsumoRepository, IFaturaSaneamentoRepository, IArrecadacaoSaneamentoRepository, IParcelamentoSaneamentoRepository, IOrdemServicoSaneamentoRepository, IEquipeCampoSaneamentoRepository, ILaboratorioSaneamentoRepository, IRedeSaneamentoRepository, ISaneamentoDashboardRepository, ISaneamentoExportacaoRepository, ISaneamentoSequencialService
{
    private readonly DapperContext _context;
    public SaneamentoRepository(DapperContext context) => _context = context;
    private static int Offset(int page,int size)=>(Math.Max(1,page)-1)*Math.Clamp(size,1,100);
    private static int Limit(int size)=>Math.Clamp(size,1,100);
    private static string Like(string? termo)=>$"%{(termo??string.Empty).Trim()}%";

    public async Task<string> ProximoAsync(long tenantId,long entidadeId,string prefixo,CancellationToken ct)
    {
        var ano=DateTimeOffset.UtcNow.Year.ToString(CultureInfo.InvariantCulture);
        var table=prefixo switch { "CON"=>"saneamento_consumidor", "LIG"=>"saneamento_ligacao", "UC"=>"saneamento_unidade_consumidora", "FAT"=>"saneamento_fatura", "ARR-SAN"=>"saneamento_arrecadacao", "PARC-SAN"=>"saneamento_parcelamento", "OS-SAN"=>"saneamento_ordem_servico", "AMO"=>"saneamento_laboratorio_amostra", "RED"=>"saneamento_rede_trecho", "EQ-SAN"=>"saneamento_equipe_campo", _=>"saneamento_evento" };
        var column=prefixo switch { "CON"=>"codigo_consumidor", "LIG"=>"numero_ligacao", "UC"=>"codigo_unidade", "FAT" or "ARR-SAN" or "PARC-SAN" or "OS-SAN" or "AMO"=>"numero", "RED" or "EQ-SAN"=>"codigo", _=>"tipo_evento" };
        var sql=$"select count(*) + 1 from sigov.{table} where tenant_id=@TenantId and entidade_id=@EntidadeId and {column} like @Pattern;";
        using var cn=_context.CreateConnection();
        var n=await cn.ExecuteScalarAsync<long>(new CommandDefinition(sql,new{TenantId=tenantId,EntidadeId=entidadeId,Pattern=$"{prefixo}-{ano}-%"},cancellationToken:ct)).ConfigureAwait(false);
        return $"{prefixo}-{ano}-{n:000000}";
    }

    async Task<PagedResult<SaneamentoConsumidorResponse>> ISaneamentoConsumidorRepository.ListarAsync(long tenantId,long entidadeId,SaneamentoConsumidorFiltro f,CancellationToken ct){const string where="tenant_id=@TenantId and entidade_id=@EntidadeId and is_deleted=false and (@Situacao is null or situacao=@Situacao) and (@Termo='' or codigo_consumidor ilike @Like)"; using var cn=_context.CreateConnection(); var total=await cn.ExecuteScalarAsync<long>(new CommandDefinition($"select count(*) from sigov.saneamento_consumidor where {where}",new{TenantId=tenantId,EntidadeId=entidadeId,f.Situacao,Termo=f.Termo??"",Like=Like(f.Termo)},cancellationToken:ct)); var rows=await cn.QueryAsync<SaneamentoConsumidorResponse>(new CommandDefinition($"select c.id as Id,c.pessoa_id as PessoaId,c.codigo_consumidor as CodigoConsumidor,c.tipo_consumidor as TipoConsumidor,c.situacao as Situacao, left(coalesce(p.nome_social,p.nome,''),3)||'***' as NomePessoa from sigov.saneamento_consumidor c left join sigov.pessoa p on p.id=c.pessoa_id and p.tenant_id=c.tenant_id where c.tenant_id=@TenantId and c.entidade_id=@EntidadeId and c.is_deleted=false and (@Situacao is null or c.situacao=@Situacao) and (@Termo='' or c.codigo_consumidor ilike @Like) order by c.id desc limit @Limit offset @Offset",new{TenantId=tenantId,EntidadeId=entidadeId,f.Situacao,Termo=f.Termo??"",Like=Like(f.Termo),Limit=Limit(f.PageSize),Offset=Offset(f.Page,f.PageSize)},cancellationToken:ct)); return new(rows.AsList(),f.Page,f.PageSize,total);}
    async Task<SaneamentoConsumidorResponse?> ISaneamentoConsumidorRepository.ObterAsync(long tenantId,long entidadeId,long id,bool completo,CancellationToken ct){using var cn=_context.CreateConnection(); var nome=completo?"coalesce(p.nome_social,p.nome,'')":"left(coalesce(p.nome_social,p.nome,''),3)||'***'"; return await cn.QuerySingleOrDefaultAsync<SaneamentoConsumidorResponse>(new CommandDefinition($"select c.id as Id,c.pessoa_id as PessoaId,c.codigo_consumidor as CodigoConsumidor,c.tipo_consumidor as TipoConsumidor,c.situacao as Situacao,{nome} as NomePessoa from sigov.saneamento_consumidor c left join sigov.pessoa p on p.id=c.pessoa_id and p.tenant_id=c.tenant_id where c.tenant_id=@TenantId and c.entidade_id=@EntidadeId and c.id=@Id and c.is_deleted=false",new{TenantId=tenantId,EntidadeId=entidadeId,Id=id},cancellationToken:ct));}
    async Task<long> ISaneamentoConsumidorRepository.CriarAsync(long tenantId,long entidadeId,long? usuarioId,SaneamentoConsumidorCreateRequest r,string codigo,CancellationToken ct){const string sql="insert into sigov.saneamento_consumidor(tenant_id,entidade_id,pessoa_id,codigo_consumidor,tipo_consumidor,situacao,observacao,created_by) values(@TenantId,@EntidadeId,@PessoaId,@Codigo,@Tipo,@Situacao,@Observacao,@UsuarioId) returning id"; using var cn=_context.CreateConnection(); return await cn.ExecuteScalarAsync<long>(new CommandDefinition(sql,new{TenantId=tenantId,EntidadeId=entidadeId,r.PessoaId,Codigo=codigo,Tipo=r.TipoConsumidor,Situacao=r.Situacao,r.Observacao,UsuarioId=usuarioId},cancellationToken:ct));}
    async Task ISaneamentoConsumidorRepository.AtualizarAsync(long tenantId,long entidadeId,long id,long? usuarioId,SaneamentoConsumidorUpdateRequest r,CancellationToken ct){const string sql="update sigov.saneamento_consumidor set codigo_consumidor=@CodigoConsumidor,tipo_consumidor=@TipoConsumidor,situacao=@Situacao,observacao=@Observacao,updated_by=@UsuarioId,updated_at=now() where tenant_id=@TenantId and entidade_id=@EntidadeId and id=@Id and is_deleted=false"; using var cn=_context.CreateConnection(); await cn.ExecuteAsync(new CommandDefinition(sql,new{TenantId=tenantId,EntidadeId=entidadeId,Id=id,UsuarioId=usuarioId,r.CodigoConsumidor,r.TipoConsumidor,r.Situacao,r.Observacao},cancellationToken:ct));}
    async Task ISaneamentoConsumidorRepository.ExcluirAsync(long tenantId,long entidadeId,long id,long? usuarioId,CancellationToken ct)=>await Soft("saneamento_consumidor",tenantId,entidadeId,id,usuarioId,ct);
    private async Task Soft(string table,long tenantId,long entidadeId,long id,long? usuarioId,CancellationToken ct){using var cn=_context.CreateConnection(); await cn.ExecuteAsync(new CommandDefinition($"update sigov.{table} set is_deleted=true,ativo=false,deleted_at=now(),deleted_by=@UsuarioId where tenant_id=@TenantId and entidade_id=@EntidadeId and id=@Id and is_deleted=false",new{TenantId=tenantId,EntidadeId=entidadeId,Id=id,UsuarioId=usuarioId},cancellationToken:ct));}

    async Task<PagedResult<LigacaoSaneamentoResponse>> ILigacaoSaneamentoRepository.ListarAsync(long t,long e,SaneamentoFiltro f,CancellationToken ct){using var cn=_context.CreateConnection(); const string w="tenant_id=@TenantId and entidade_id=@EntidadeId and is_deleted=false and (@Status is null or situacao=@Status)"; var p=new{TenantId=t,EntidadeId=e,f.Status,Limit=Limit(f.PageSize),Offset=Offset(f.Page,f.PageSize)}; var total=await cn.ExecuteScalarAsync<long>(new CommandDefinition($"select count(*) from sigov.saneamento_ligacao where {w}",p,cancellationToken:ct)); var rows=await cn.QueryAsync<LigacaoSaneamentoResponse>(new CommandDefinition($"select id as Id,consumidor_id as ConsumidorId,numero_ligacao as NumeroLigacao,tipo_ligacao as TipoLigacao,situacao as Situacao,categoria as Categoria,economia as Economia from sigov.saneamento_ligacao where {w} order by id desc limit @Limit offset @Offset",p,cancellationToken:ct)); return new(rows.AsList(),f.Page,f.PageSize,total);}
    async Task<LigacaoSaneamentoResponse?> ILigacaoSaneamentoRepository.ObterAsync(long t,long e,long id,CancellationToken ct){using var cn=_context.CreateConnection(); return await cn.QuerySingleOrDefaultAsync<LigacaoSaneamentoResponse>(new CommandDefinition("select id as Id,consumidor_id as ConsumidorId,numero_ligacao as NumeroLigacao,tipo_ligacao as TipoLigacao,situacao as Situacao,categoria as Categoria,economia as Economia from sigov.saneamento_ligacao where tenant_id=@TenantId and entidade_id=@EntidadeId and id=@Id and is_deleted=false",new{TenantId=t,EntidadeId=e,Id=id},cancellationToken:ct));}
    async Task<long> ILigacaoSaneamentoRepository.CriarAsync(long t,long e,long? u,LigacaoSaneamentoCreateRequest r,string numero,CancellationToken ct){using var cn=_context.CreateConnection(); var situacaoConsumidor = await cn.ExecuteScalarAsync<string>(new CommandDefinition("select situacao from sigov.saneamento_consumidor where tenant_id=@TenantId and entidade_id=@EntidadeId and id=@ConsumidorId and is_deleted=false",new{TenantId=t,EntidadeId=e,r.ConsumidorId},cancellationToken:ct)).ConfigureAwait(false); if(string.IsNullOrWhiteSpace(situacaoConsumidor) || !situacaoConsumidor.Equals("ATIVO", StringComparison.OrdinalIgnoreCase)) throw new InvalidOperationException("Cliente inativo não pode receber nova ligação."); return await cn.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.saneamento_ligacao(tenant_id,entidade_id,consumidor_id,numero_ligacao,tipo_ligacao,situacao,data_ligacao,categoria,economia,observacao,created_by) values(@TenantId,@EntidadeId,@ConsumidorId,@Numero,@Tipo,@Situacao,@DataLigacao,@Categoria,@Economia,@Observacao,@UsuarioId) returning id",new{TenantId=t,EntidadeId=e,r.ConsumidorId,Numero=numero,Tipo=r.TipoLigacao,r.Situacao,r.DataLigacao,r.Categoria,r.Economia,r.Observacao,UsuarioId=u},cancellationToken:ct));}
    async Task ILigacaoSaneamentoRepository.AtualizarAsync(long t,long e,long id,long? u,LigacaoSaneamentoUpdateRequest r,CancellationToken ct){using var cn=_context.CreateConnection(); await cn.ExecuteAsync(new CommandDefinition("update sigov.saneamento_ligacao set numero_ligacao=@NumeroLigacao,tipo_ligacao=@TipoLigacao,situacao=@Situacao,categoria=@Categoria,economia=@Economia,data_ligacao=@DataLigacao,data_corte=@DataCorte,observacao=@Observacao,updated_by=@UsuarioId,updated_at=now() where tenant_id=@TenantId and entidade_id=@EntidadeId and id=@Id and is_deleted=false",new{TenantId=t,EntidadeId=e,Id=id,UsuarioId=u,r.NumeroLigacao,r.TipoLigacao,r.Situacao,r.Categoria,r.Economia,r.DataLigacao,r.DataCorte,r.Observacao},cancellationToken:ct));}
    async Task ILigacaoSaneamentoRepository.ExcluirAsync(long t,long e,long id,long? u,CancellationToken ct)=>await Soft("saneamento_ligacao",t,e,id,u,ct);

    async Task<PagedResult<UnidadeConsumidoraResponse>> IUnidadeConsumidoraRepository.ListarAsync(long t,long e,UnidadeConsumidoraFiltro f,CancellationToken ct){using var cn=_context.CreateConnection(); const string w="tenant_id=@TenantId and entidade_id=@EntidadeId and is_deleted=false and (@Situacao is null or situacao=@Situacao) and (@Rota is null or rota=@Rota)"; var p=new{TenantId=t,EntidadeId=e,f.Situacao,f.Rota,Limit=Limit(f.PageSize),Offset=Offset(f.Page,f.PageSize)}; var total=await cn.ExecuteScalarAsync<long>(new CommandDefinition($"select count(*) from sigov.saneamento_unidade_consumidora where {w}",p,cancellationToken:ct)); var rows=await cn.QueryAsync<UnidadeConsumidoraResponse>(new CommandDefinition($"select id as Id,consumidor_id as ConsumidorId,ligacao_id as LigacaoId,codigo_unidade as CodigoUnidade,bairro as Bairro,rota as Rota,sequencia_rota as SequenciaRota,latitude as Latitude,longitude as Longitude,situacao as Situacao from sigov.saneamento_unidade_consumidora where {w} order by id desc limit @Limit offset @Offset",p,cancellationToken:ct)); return new(rows.AsList(),f.Page,f.PageSize,total);}
    async Task<UnidadeConsumidoraResponse?> IUnidadeConsumidoraRepository.ObterAsync(long t,long e,long id,CancellationToken ct){using var cn=_context.CreateConnection(); return await cn.QuerySingleOrDefaultAsync<UnidadeConsumidoraResponse>(new CommandDefinition("select id as Id,consumidor_id as ConsumidorId,ligacao_id as LigacaoId,codigo_unidade as CodigoUnidade,bairro as Bairro,rota as Rota,sequencia_rota as SequenciaRota,latitude as Latitude,longitude as Longitude,situacao as Situacao from sigov.saneamento_unidade_consumidora where tenant_id=@TenantId and entidade_id=@EntidadeId and id=@Id and is_deleted=false",new{TenantId=t,EntidadeId=e,Id=id},cancellationToken:ct));}
    async Task<long> IUnidadeConsumidoraRepository.CriarAsync(long t,long e,long? u,UnidadeConsumidoraCreateRequest r,string codigo,CancellationToken ct){using var cn=_context.CreateConnection(); return await cn.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.saneamento_unidade_consumidora(tenant_id,entidade_id,consumidor_id,ligacao_id,codigo_unidade,endereco_json,bairro,setor,rota,sequencia_rota,latitude,longitude,situacao,created_by) values(@TenantId,@EntidadeId,@ConsumidorId,@LigacaoId,@Codigo,cast(@EnderecoJson as jsonb),@Bairro,@Setor,@Rota,@SequenciaRota,@Latitude,@Longitude,@Situacao,@UsuarioId) returning id",new{TenantId=t,EntidadeId=e,r.ConsumidorId,r.LigacaoId,Codigo=codigo,r.EnderecoJson,r.Bairro,r.Setor,r.Rota,r.SequenciaRota,r.Latitude,r.Longitude,r.Situacao,UsuarioId=u},cancellationToken:ct));}
    async Task IUnidadeConsumidoraRepository.AtualizarAsync(long t,long e,long id,long? u,UnidadeConsumidoraUpdateRequest r,CancellationToken ct){using var cn=_context.CreateConnection(); await cn.ExecuteAsync(new CommandDefinition("update sigov.saneamento_unidade_consumidora set ligacao_id=@LigacaoId,codigo_unidade=@CodigoUnidade,endereco_json=cast(@EnderecoJson as jsonb),bairro=@Bairro,setor=@Setor,rota=@Rota,sequencia_rota=@SequenciaRota,latitude=@Latitude,longitude=@Longitude,situacao=@Situacao,updated_by=@UsuarioId,updated_at=now() where tenant_id=@TenantId and entidade_id=@EntidadeId and id=@Id and is_deleted=false",new{TenantId=t,EntidadeId=e,Id=id,UsuarioId=u,r.LigacaoId,r.CodigoUnidade,r.EnderecoJson,r.Bairro,r.Setor,r.Rota,r.SequenciaRota,r.Latitude,r.Longitude,r.Situacao},cancellationToken:ct));}
    async Task IUnidadeConsumidoraRepository.ExcluirAsync(long t,long e,long id,long? u,CancellationToken ct)=>await Soft("saneamento_unidade_consumidora",t,e,id,u,ct);

    async Task<PagedResult<HidrometroResponse>> IHidrometroRepository.ListarAsync(long t,long e,SaneamentoFiltro f,CancellationToken ct){using var cn=_context.CreateConnection(); const string w="tenant_id=@TenantId and entidade_id=@EntidadeId and is_deleted=false and (@UnidadeConsumidoraId is null or unidade_consumidora_id=@UnidadeConsumidoraId)"; var p=new{TenantId=t,EntidadeId=e,f.UnidadeConsumidoraId,Limit=Limit(f.PageSize),Offset=Offset(f.Page,f.PageSize)}; var total=await cn.ExecuteScalarAsync<long>(new CommandDefinition($"select count(*) from sigov.saneamento_hidrometro where {w}",p,cancellationToken:ct)); var rows=await cn.QueryAsync<HidrometroResponse>(new CommandDefinition($"select id as Id,unidade_consumidora_id as UnidadeConsumidoraId,numero_serie as NumeroSerie,marca as Marca,modelo as Modelo,situacao as Situacao from sigov.saneamento_hidrometro where {w} order by id desc limit @Limit offset @Offset",p,cancellationToken:ct)); return new(rows.AsList(),f.Page,f.PageSize,total);}
    async Task<long> IHidrometroRepository.CriarAsync(long t,long e,long? u,HidrometroCreateRequest r,CancellationToken ct){using var cn=_context.CreateConnection(); if(string.Equals(r.Situacao, "INSTALADO", StringComparison.OrdinalIgnoreCase)){ var jaInstalado = await cn.ExecuteScalarAsync<int>(new CommandDefinition("select count(*) from sigov.saneamento_hidrometro where tenant_id=@TenantId and entidade_id=@EntidadeId and unidade_consumidora_id=@UnidadeConsumidoraId and situacao='INSTALADO' and is_deleted=false", new { TenantId = t, EntidadeId = e, r.UnidadeConsumidoraId }, cancellationToken: ct)).ConfigureAwait(false); if(jaInstalado > 0) throw new InvalidOperationException("Já existe hidrômetro INSTALADO nesta ligação."); } return await cn.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.saneamento_hidrometro(tenant_id,entidade_id,unidade_consumidora_id,numero_serie,marca,modelo,diametro,data_instalacao,leitura_instalacao,situacao,created_by) values(@TenantId,@EntidadeId,@UnidadeConsumidoraId,@NumeroSerie,@Marca,@Modelo,@Diametro,@DataInstalacao,@LeituraInstalacao,@Situacao,@UsuarioId) returning id",new{TenantId=t,EntidadeId=e,r.UnidadeConsumidoraId,r.NumeroSerie,r.Marca,r.Modelo,r.Diametro,r.DataInstalacao,r.LeituraInstalacao,r.Situacao,UsuarioId=u},cancellationToken:ct));}
    async Task<long> IHidrometroRepository.SubstituirAsync(long t,long e,long? u,long hidrometroAtualId,HidrometroCreateRequest r,CancellationToken ct){using var cn=_context.CreateConnection(); cn.Open(); using var tx=cn.BeginTransaction(); await cn.ExecuteAsync(new CommandDefinition("update sigov.saneamento_hidrometro set situacao='SUBSTITUIDO',data_retirada=current_date,updated_at=now(),updated_by=@UsuarioId where tenant_id=@TenantId and entidade_id=@EntidadeId and id=@Id and is_deleted=false",new{TenantId=t,EntidadeId=e,Id=hidrometroAtualId,UsuarioId=u},transaction:tx,cancellationToken:ct)).ConfigureAwait(false); var novoId = await cn.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.saneamento_hidrometro(tenant_id,entidade_id,unidade_consumidora_id,numero_serie,marca,modelo,diametro,data_instalacao,leitura_instalacao,situacao,created_by) values(@TenantId,@EntidadeId,@UnidadeConsumidoraId,@NumeroSerie,@Marca,@Modelo,@Diametro,@DataInstalacao,@LeituraInstalacao,'INSTALADO',@UsuarioId) returning id",new{TenantId=t,EntidadeId=e,r.UnidadeConsumidoraId,r.NumeroSerie,r.Marca,r.Modelo,r.Diametro,r.DataInstalacao,r.LeituraInstalacao,UsuarioId=u},transaction:tx,cancellationToken:ct)).ConfigureAwait(false); tx.Commit(); return novoId;}
    async Task IHidrometroRepository.AtualizarAsync(long t,long e,long id,long? u,HidrometroUpdateRequest r,CancellationToken ct){using var cn=_context.CreateConnection(); if(string.Equals(r.Situacao, "INSTALADO", StringComparison.OrdinalIgnoreCase)){ var jaInstalado = await cn.ExecuteScalarAsync<int>(new CommandDefinition("select count(*) from sigov.saneamento_hidrometro where tenant_id=@TenantId and entidade_id=@EntidadeId and id <> @Id and unidade_consumidora_id=(select unidade_consumidora_id from sigov.saneamento_hidrometro where id=@Id and tenant_id=@TenantId and entidade_id=@EntidadeId) and situacao='INSTALADO' and is_deleted=false", new { TenantId = t, EntidadeId = e, Id = id }, cancellationToken: ct)).ConfigureAwait(false); if(jaInstalado > 0) throw new InvalidOperationException("Já existe hidrômetro INSTALADO nesta ligação."); } await cn.ExecuteAsync(new CommandDefinition("update sigov.saneamento_hidrometro set numero_serie=@NumeroSerie,marca=@Marca,modelo=@Modelo,diametro=@Diametro,data_instalacao=@DataInstalacao,data_retirada=@DataRetirada,leitura_instalacao=@LeituraInstalacao,situacao=@Situacao,updated_by=@UsuarioId,updated_at=now() where tenant_id=@TenantId and entidade_id=@EntidadeId and id=@Id and is_deleted=false",new{TenantId=t,EntidadeId=e,Id=id,UsuarioId=u,r.NumeroSerie,r.Marca,r.Modelo,r.Diametro,r.DataInstalacao,r.DataRetirada,r.LeituraInstalacao,r.Situacao},cancellationToken:ct));}
    async Task IHidrometroRepository.ExcluirAsync(long t,long e,long id,long? u,CancellationToken ct)=>await Soft("saneamento_hidrometro",t,e,id,u,ct);

    async Task<PagedResult<LeituraConsumoResponse>> ILeituraConsumoRepository.ListarAsync(long t,long e,LeituraConsumoFiltro f,CancellationToken ct){using var cn=_context.CreateConnection(); const string w="tenant_id=@TenantId and entidade_id=@EntidadeId and is_deleted=false and (@UnidadeConsumidoraId is null or unidade_consumidora_id=@UnidadeConsumidoraId) and (@Competencia is null or competencia=@Competencia)"; var p=new{TenantId=t,EntidadeId=e,f.UnidadeConsumidoraId,f.Competencia,Limit=Limit(f.PageSize),Offset=Offset(f.Page,f.PageSize)}; var total=await cn.ExecuteScalarAsync<long>(new CommandDefinition($"select count(*) from sigov.saneamento_leitura where {w}",p,cancellationToken:ct)); var rows=await cn.QueryAsync<LeituraConsumoResponse>(new CommandDefinition($"select id as Id,unidade_consumidora_id as UnidadeConsumidoraId,hidrometro_id as HidrometroId,competencia as Competencia,data_leitura as DataLeitura,leitura_anterior as LeituraAnterior,leitura_atual as LeituraAtual,consumo_medido as ConsumoMedido,consumo_faturado as ConsumoFaturado,tipo_leitura as TipoLeitura from sigov.saneamento_leitura where {w} order by data_leitura desc,id desc limit @Limit offset @Offset",p,cancellationToken:ct)); return new(rows.AsList(),f.Page,f.PageSize,total);}
    async Task<LeituraConsumoResponse?> ILeituraConsumoRepository.ObterAsync(long t,long e,long id,CancellationToken ct){using var cn=_context.CreateConnection(); return await cn.QuerySingleOrDefaultAsync<LeituraConsumoResponse>(new CommandDefinition("select id as Id,unidade_consumidora_id as UnidadeConsumidoraId,hidrometro_id as HidrometroId,competencia as Competencia,data_leitura as DataLeitura,leitura_anterior as LeituraAnterior,leitura_atual as LeituraAtual,consumo_medido as ConsumoMedido,consumo_faturado as ConsumoFaturado,tipo_leitura as TipoLeitura from sigov.saneamento_leitura where tenant_id=@TenantId and entidade_id=@EntidadeId and id=@Id and is_deleted=false",new{TenantId=t,EntidadeId=e,Id=id},cancellationToken:ct));}
    async Task<long> ILeituraConsumoRepository.CriarAsync(long t,long e,long? ex,long? u,LeituraConsumoCreateRequest r,decimal medido,decimal faturado,CancellationToken ct){using var cn=_context.CreateConnection(); var hidrometroInstalado = await cn.ExecuteScalarAsync<long?>(new CommandDefinition("select id from sigov.saneamento_hidrometro where tenant_id=@TenantId and entidade_id=@EntidadeId and unidade_consumidora_id=@UnidadeConsumidoraId and situacao='INSTALADO' and is_deleted=false limit 1", new { TenantId = t, EntidadeId = e, r.UnidadeConsumidoraId }, cancellationToken: ct)).ConfigureAwait(false); if(!hidrometroInstalado.HasValue) throw new InvalidOperationException("A unidade consumidora não possui hidrômetro INSTALADO para leitura."); if(r.LeituraAtual < r.LeituraAnterior && string.IsNullOrWhiteSpace(r.Ocorrencia)) throw new InvalidOperationException("Leitura menor que a anterior. Confira a troca do hidrômetro."); var jaLeu = await cn.ExecuteScalarAsync<int>(new CommandDefinition("select count(*) from sigov.saneamento_leitura where tenant_id=@TenantId and entidade_id=@EntidadeId and unidade_consumidora_id=@UnidadeConsumidoraId and competencia=@Competencia and is_deleted=false", new { TenantId = t, EntidadeId = e, r.UnidadeConsumidoraId, r.Competencia }, cancellationToken: ct)).ConfigureAwait(false); if(jaLeu > 0) throw new InvalidOperationException("Já existe leitura registrada para esta competência."); var hidrometroId = r.HidrometroId ?? hidrometroInstalado; return await cn.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.saneamento_leitura(tenant_id,entidade_id,exercicio_id,unidade_consumidora_id,hidrometro_id,competencia,data_leitura,leitura_anterior,leitura_atual,consumo_medido,consumo_faturado,tipo_leitura,ocorrencia,latitude,longitude,observacao,created_by) values(@TenantId,@EntidadeId,@ExercicioId,@UnidadeConsumidoraId,@HidrometroId,@Competencia,@DataLeitura,@LeituraAnterior,@LeituraAtual,@Medido,@Faturado,@TipoLeitura,@Ocorrencia,@Latitude,@Longitude,@Observacao,@UsuarioId) returning id",new{TenantId=t,EntidadeId=e,ExercicioId=ex,r.UnidadeConsumidoraId,HidrometroId=hidrometroId,r.Competencia,r.DataLeitura,r.LeituraAnterior,r.LeituraAtual,Medido=medido,Faturado=faturado,r.TipoLeitura,r.Ocorrencia,r.Latitude,r.Longitude,r.Observacao,UsuarioId=u},cancellationToken:ct));}

