    async Task<long> IFaturaSaneamentoRepository.CriarAsync(long t,long e,long? ex,long? u,FaturaSaneamentoCreateRequest r,string numero,decimal total,string ambiente,CancellationToken ct){using var cn=_context.CreateConnection(); var tarifasAtivas = await cn.ExecuteScalarAsync<int>(new CommandDefinition("select count(*) from sigov.saneamento_tarifa where tenant_id=@TenantId and (entidade_id=@EntidadeId or entidade_id is null) and status='ATIVO' and is_deleted=false", new { TenantId = t, EntidadeId = e }, cancellationToken: ct)).ConfigureAwait(false); if(tarifasAtivas == 0) throw new InvalidOperationException("Não há parâmetro tarifário para esta competência."); var clienteAtivo = await cn.ExecuteScalarAsync<int>(new CommandDefinition("select count(*) from sigov.saneamento_unidade_consumidora uc inner join sigov.saneamento_consumidor c on c.id=uc.consumidor_id and c.tenant_id=uc.tenant_id and c.entidade_id=uc.entidade_id where uc.tenant_id=@TenantId and uc.entidade_id=@EntidadeId and uc.id=@UnidadeConsumidoraId and c.situacao='ATIVO' and c.is_deleted=false and uc.is_deleted=false", new { TenantId = t, EntidadeId = e, r.UnidadeConsumidoraId }, cancellationToken: ct)).ConfigureAwait(false); if(clienteAtivo == 0) throw new InvalidOperationException("Cliente inativo não pode receber nova fatura."); return await cn.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.saneamento_fatura(tenant_id,entidade_id,exercicio_id,unidade_consumidora_id,leitura_id,numero,competencia,data_vencimento,valor_agua,valor_esgoto,valor_servicos,valor_multa,valor_juros,valor_desconto,valor_total,status,codigo_barras,linha_digitavel,ambiente,created_by) values(@TenantId,@EntidadeId,@ExercicioId,@UnidadeConsumidoraId,@LeituraId,@Numero,@Competencia,@DataVencimento,@ValorAgua,@ValorEsgoto,@ValorServicos,@ValorMulta,@ValorJuros,@ValorDesconto,@Total,'ABERTA',null,null,@Ambiente,@UsuarioId) returning id",new{TenantId=t,EntidadeId=e,ExercicioId=ex,r.UnidadeConsumidoraId,r.LeituraId,Numero=numero,r.Competencia,r.DataVencimento,r.ValorAgua,r.ValorEsgoto,r.ValorServicos,r.ValorMulta,r.ValorJuros,r.ValorDesconto,Total=total,Ambiente=ambiente,UsuarioId=u},cancellationToken:ct));}
    async Task<long> IFaturaSaneamentoRepository.GerarPorLeituraAsync(long t,long e,long? ex,long leituraId,long? u,GerarFaturaPorLeituraRequest r,string numero,string ambiente,CancellationToken ct){using var cn=_context.CreateConnection(); var tarifasAtivas = await cn.ExecuteScalarAsync<int>(new CommandDefinition("select count(*) from sigov.saneamento_tarifa where tenant_id=@TenantId and (entidade_id=@EntidadeId or entidade_id is null) and status='ATIVO' and is_deleted=false", new { TenantId = t, EntidadeId = e }, cancellationToken: ct)).ConfigureAwait(false); if(tarifasAtivas == 0) throw new InvalidOperationException("Não há parâmetro tarifário para esta competência."); var ucId = await cn.ExecuteScalarAsync<long?>(new CommandDefinition("select unidade_consumidora_id from sigov.saneamento_leitura where tenant_id=@TenantId and entidade_id=@EntidadeId and id=@LeituraId and is_deleted=false", new { TenantId = t, EntidadeId = e, LeituraId = leituraId }, cancellationToken: ct)).ConfigureAwait(false); if(!ucId.HasValue) throw new InvalidOperationException("Leitura não encontrada para faturamento."); var clienteAtivoLeitura = await cn.ExecuteScalarAsync<int>(new CommandDefinition("select count(*) from sigov.saneamento_unidade_consumidora uc inner join sigov.saneamento_consumidor c on c.id=uc.consumidor_id and c.tenant_id=uc.tenant_id and c.entidade_id=uc.entidade_id where uc.tenant_id=@TenantId and uc.entidade_id=@EntidadeId and uc.id=@UcId and c.situacao='ATIVO' and c.is_deleted=false and uc.is_deleted=false", new { TenantId = t, EntidadeId = e, UcId = ucId.Value }, cancellationToken: ct)).ConfigureAwait(false); if(clienteAtivoLeitura == 0) throw new InvalidOperationException("Cliente inativo não pode receber nova fatura."); const string sql="insert into sigov.saneamento_fatura(tenant_id,entidade_id,exercicio_id,unidade_consumidora_id,leitura_id,numero,competencia,data_vencimento,valor_agua,valor_esgoto,valor_servicos,valor_total,status,codigo_barras,linha_digitavel,ambiente,created_by) select tenant_id,entidade_id,@ExercicioId,unidade_consumidora_id,id,@Numero,competencia,@DataVencimento,consumo_faturado*@TarifaAgua,consumo_faturado*@TarifaEsgoto,@ValorServicos,(consumo_faturado*@TarifaAgua)+(consumo_faturado*@TarifaEsgoto)+@ValorServicos,'ABERTA',null,null,@Ambiente,@UsuarioId from sigov.saneamento_leitura where tenant_id=@TenantId and entidade_id=@EntidadeId and id=@LeituraId and is_deleted=false returning id"; return await cn.ExecuteScalarAsync<long>(new CommandDefinition(sql,new{TenantId=t,EntidadeId=e,ExercicioId=ex,LeituraId=leituraId,Numero=numero,r.DataVencimento,r.TarifaAgua,r.TarifaEsgoto,r.ValorServicos,Ambiente=ambiente,UsuarioId=u},cancellationToken:ct));}
    async Task IFaturaSaneamentoRepository.CancelarAsync(long t,long e,long id,long? u,string motivo,CancellationToken ct){using var cn=_context.CreateConnection(); await cn.ExecuteAsync(new CommandDefinition("update sigov.saneamento_fatura set status='CANCELADA',updated_by=@UsuarioId,updated_at=now() where tenant_id=@TenantId and entidade_id=@EntidadeId and id=@Id and status <> 'PAGA'",new{TenantId=t,EntidadeId=e,Id=id,UsuarioId=u,Motivo=motivo},cancellationToken:ct));}
    async Task<ArrecadacaoSaneamentoResponse> IFaturaSaneamentoRepository.RegistrarPagamentoDevAsync(long t,long e,long? ex,long id,long? u,RegistrarPagamentoDevRequest r,string numero,CancellationToken ct){using var cn=_context.CreateConnection(); cn.Open(); using var tx=cn.BeginTransaction(); var f=await cn.QuerySingleAsync<(decimal ValorTotal,decimal ValorPago,string Status)>(new CommandDefinition("select valor_total as ValorTotal,valor_pago as ValorPago,status as Status from sigov.saneamento_fatura where tenant_id=@TenantId and entidade_id=@EntidadeId and id=@Id and is_deleted=false for update",new{TenantId=t,EntidadeId=e,Id=id},transaction:tx,cancellationToken:ct)); if(f.Status is "PAGA" or "CANCELADA") throw new InvalidOperationException("Fatura não pode receber pagamento."); if(r.ValorPago<=0 || r.ValorPago>f.ValorTotal-f.ValorPago) throw new InvalidOperationException("Valor maior que o saldo da fatura."); var aid=await cn.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.saneamento_arrecadacao(tenant_id,entidade_id,exercicio_id,fatura_id,numero,data_pagamento,forma_pagamento,valor_pago,origem,metadados,created_by) values(@TenantId,@EntidadeId,@ExercicioId,@FaturaId,@Numero,@DataPagamento,'MANUAL_DEV',@ValorPago,@Origem,'{}'::jsonb,@UsuarioId) returning id",new{TenantId=t,EntidadeId=e,ExercicioId=ex,FaturaId=id,Numero=numero,DataPagamento=r.DataPagamento??DateOnly.FromDateTime(DateTime.UtcNow),r.ValorPago,r.Origem,UsuarioId=u},transaction:tx,cancellationToken:ct)); var novo=f.ValorPago+r.ValorPago; await cn.ExecuteAsync(new CommandDefinition("update sigov.saneamento_fatura set valor_pago=@ValorPago,status=case when @ValorPago>=valor_total then 'PAGA' else status end,updated_at=now(),updated_by=@UsuarioId where tenant_id=@TenantId and entidade_id=@EntidadeId and id=@Id",new{TenantId=t,EntidadeId=e,Id=id,ValorPago=novo,UsuarioId=u},transaction:tx,cancellationToken:ct)); tx.Commit(); return new(aid,id,numero,r.DataPagamento??DateOnly.FromDateTime(DateTime.UtcNow),"MANUAL_DEV",r.ValorPago);}

