    async Task IOrdemServicoSaneamentoRepository.ExecutarAsync(long t,long e,long? ex,long id,long? u,ExecutarOrdemServicoRequest r,CancellationToken ct){if(string.IsNullOrWhiteSpace(r.Solucao)) throw new ArgumentException("O encerramento da ordem de serviço exige relatório da solução."); using var cn=_context.CreateConnection(); cn.Open(); using var tx=cn.BeginTransaction(); await cn.ExecuteAsync(new CommandDefinition("update sigov.saneamento_ordem_servico set status='EXECUTADA',solucao=@Solucao,data_execucao=now(),equipe_campo_id=coalesce(@EquipeCampoId,equipe_campo_id),updated_by=@UsuarioId,updated_at=now() where tenant_id=@TenantId and entidade_id=@EntidadeId and id=@Id and status <> 'CANCELADA'",new{TenantId=t,EntidadeId=e,Id=id,r.Solucao,r.EquipeCampoId,UsuarioId=u},transaction:tx,cancellationToken:ct)); await cn.ExecuteAsync(new CommandDefinition("insert into sigov.saneamento_servico_executado(tenant_id,entidade_id,exercicio_id,ordem_servico_id,tipo_servico,descricao,equipe_campo_id,materiais_json,evidencias_json,created_by) select tenant_id,entidade_id,@ExercicioId,id,tipo_servico,@Solucao,@EquipeCampoId,cast(@Materiais as jsonb),cast(@Evidencias as jsonb),@UsuarioId from sigov.saneamento_ordem_servico where tenant_id=@TenantId and entidade_id=@EntidadeId and id=@Id",new{TenantId=t,EntidadeId=e,ExercicioId=ex,Id=id,r.Solucao,r.EquipeCampoId,Materiais=r.MateriaisJson??"[]",Evidencias=r.EvidenciasJson??"[]",UsuarioId=u},transaction:tx,cancellationToken:ct)); tx.Commit();}
